var a = 1, b = 0;
function draw() {
  api.clear();
  var ax = api.axes({ xmin: -5, xmax: 5, ymin: -5, ymax: 5, xlabel: 'x', ylabel: 'y' });
  api.plot(function (x) { return a * x + b; }, ax, { color: 'accent' });
  api.circle(ax.X(0), ax.Y(b), 4, { fill: 'text-1', stroke: 'none' });
  var s = 'f(x) = ' + String(a).replace('.', ',') + 'x ' + (b < 0 ? '− ' + String(-b).replace('.', ',') : '+ ' + String(b).replace('.', ','));
  api.text(s, 60, 24, { size: 15, bold: true, align: 'left' });
  api.text(a > 0 ? 'croissante' : a < 0 ? 'décroissante' : 'constante', 60, 44, { size: 13, color: 'text-2', align: 'left' });
}
api.slider({ label: 'Coefficient directeur a', min: -3, max: 3, step: 0.5, value: 1 }, function (v) { a = v; draw(); });
api.slider({ label: 'Ordonnée à l\'origine b', min: -4, max: 4, step: 0.5, value: 0 }, function (v) { b = v; draw(); });
draw();
